      "穀風和暖，帶來雲與雨。夫妻應當勉力同心，不該動輒發怒。掘葑菜、採菲菜，別因根部不好看就丟掉。當初的好話不要違背，我說過要和你相守到死。",
      "你走在路上拖拖拉拉，心裡早已背離了我。路其實不遠，你只把我草草送到城郊邊上。誰說荼草是苦的？它竟像薺菜一樣甘甜。你去享受你的新婚吧，願你們親熱得像兄弟一樣。",
      "涇水攪渾了渭水，水中的沙洲卻清清見底。你正忙著新婚，根本不屑顧我。別糟蹋了我搭的魚梁，別亂動我設的魚籠。我自己都顧不上歡顏，哪還能操心往後的事。",
      "遇到水深，我就找船去渡；遇到水淺，我就下水去游。家裡有什麼、缺什麼，我都勉力張羅。鄉里有人有喪事，我也匍匐著趕去幫忙。",
      "你容不下我，反把我當仇人。你把我的好心好行都攔阻，像把貨物拿到市上卻賣不出去。當年我戰戰兢兢、窮迫艱難地操持撫育；你顛躓受難時，我也一同支撐。如今兒女既生也已養大，你卻把我比作毒藥般可惡。",
      "我存下了好吃的糧餉，也是為了禦寒過冬。你正沉浸新婚的歡樂，卻還靠著我積攢的東西度窮日。忽驚忽亂，種種麻煩都丟給我來受累。你不記得從前，是我來把這個家抹泥修補起來的。"
