      "鐘鼓已設，舉杯酬酢從容安穩。大射的靶位立好，弓弦已張。射手並列而出，把命中之功獻給你。",
      "一箭射中心的靶，就藉此祈求你賜下爵賞。",
      "籥與舞步，笙與鼓點，樂聲和諧同奏。眾人欣悅饗祭列祖，使百禮俱全。禮既備舉，主持與從事者各守其位。",
      "賜你純厚的福祉，子孫長久安樂。既能安樂，人人各展所長。賓客手持酬籌行酒，內室的侍者入堂侑席。",
      "斟那吉祥的爵杯，按著時節與程序行禮。",
