      "她踐履上帝的蹤跡，迅速蒙受悅納；於是懷孕而安止，心中震懼而敬。既然生下又撫育，這孩子正是后稷。",
      "到了滿月之期，他生來順遂通達；沒有損傷撕裂，沒有災禍損害，顯出神靈的光采。",
      "即便上帝未安、禋祀未必周恰，竟也自然地得了孩子。",
      "把他放在狹巷之中，牛羊以身體的熱氣溫養他；把他放在平林之中，正好遇上伐林之人。",
      "又把他放在寒冰之上，群鳥張翼覆護他。鳥兒於是飛去，后稷啼聲響起。",
      "他漸長漸大，體魄寬厚，名聲傳遍道路。才會匍匐爬行，就已聰慧早成，還能自己找到吃食。",
      "他播種荏與菽，荏菽在風中獵獵；百穀勞作，穗實累累；麻與麥繁密成蔭，瓜與瓞連綿結實。",
      "后稷從事稼穡，自有輔助生長之法；把繁茂的雜草鏟除，播下去就黃熟茂盛；有方有苞，有種有盛。",
      "抽芽又抽穗，堅實又美好；穎粒飽滿，栗實顆顆，於是他在有邰建立家室。",
