      "我思念著泮水的歡樂，也去割取那裡的茅草。魯侯來到這裡停駐，在泮宮飲酒。既然飲了好酒，便得到長久不易衰老的福分。他順著長久正當的道路行事，使那些不善之輩屈服。",
      "魯侯莊重端穆，恭敬而彰明他的德行；他敬慎威儀，成為百姓的法則。他文武兼備，把光榮呈示於列祖列宗。人們都以孝道自求福祐，無有不然。",
